"""Inventory costing engine supporting FIFO, LIFO and weighted-average.

Processes a chronological event stream of ``Purchase`` / ``Sale`` records and
reports cost of goods sold (COGS), ending inventory quantity/value and total
purchase cost.

Design notes
------------
* All money math uses :class:`decimal.Decimal`; no floats anywhere.
* FIFO / LIFO consume cost layers; all layer costs are exact 2dp decimals, so
  every intermediate figure is exact cents.
* Weighted average is a *moving* average: it is recomputed after every
  purchase. Internally the running average is kept as an exact
  :class:`fractions.Fraction` so that repeated rounding can never accumulate;
  it is only quantized to 4 decimal places when reported as a unit cost.
* Conservation invariant (checked by the tests, including a hypothesis
  randomized test): for every method,

      cogs + ending_value == total_purchase_cost   (exact, to the cent)

  To make that hold *by construction* under cent rounding, ending_value is
  reported as the residual ``total_purchase_cost - cogs``. When cogs is not a
  half-cent tie this equals ``ending_quantity * final_average_unit_cost``
  rounded to cents anyway.
"""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP, localcontext
from fractions import Fraction
from typing import Sequence, Union

CENT = Decimal("0.01")
FOUR_DP = Decimal("0.0001")
ZERO_CENTS = Decimal("0.00")
ZERO_4DP = Decimal("0.0000")

METHODS = ("fifo", "lifo", "weighted_average")


class InsufficientInventoryError(ValueError):
    """Raised when a sale exceeds the quantity currently on hand."""


@dataclass(frozen=True)
class Purchase:
    qty: int
    unit_cost: Decimal

    def __post_init__(self) -> None:
        if self.qty <= 0:
            raise ValueError("purchase qty must be positive")
        if self.unit_cost < 0:
            raise ValueError("unit cost cannot be negative")


@dataclass(frozen=True)
class Sale:
    qty: int

    def __post_init__(self) -> None:
        if self.qty <= 0:
            raise ValueError("sale qty must be positive")


Event = Union[Purchase, Sale]


@dataclass(frozen=True)
class CostingResult:
    method: str
    cogs: Decimal                          # exact cents
    ending_quantity: int
    ending_value: Decimal                  # exact cents
    total_purchase_cost: Decimal           # exact cents
    units_sold: int
    # Final moving-average unit cost (4dp); None for fifo/lifo.
    average_unit_cost: Decimal | None = None


def _to_cents(value: Decimal | Fraction) -> Decimal:
    """Quantize to cents with ROUND_HALF_UP."""
    if isinstance(value, Fraction):
        value = _frac_to_decimal(value)
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _to_4dp(value: Decimal | Fraction) -> Decimal:
    """Quantize a unit cost to 4 decimal places with ROUND_HALF_UP."""
    if isinstance(value, Fraction):
        value = _frac_to_decimal(value)
    return value.quantize(FOUR_DP, rounding=ROUND_HALF_UP)


def _frac_to_decimal(frac: Fraction) -> Decimal:
    """Exact-enough Fraction -> Decimal conversion (plenty of precision)."""
    with localcontext() as ctx:
        ctx.prec = 50
        return Decimal(frac.numerator) / Decimal(frac.denominator)


class InventoryLedger:
    """Stateful costing engine; feed events one at a time or via ``run()``."""

    def __init__(self, method: str) -> None:
        if method not in METHODS:
            raise ValueError(
                f"unknown method {method!r}; expected one of {METHODS}"
            )
        self.method = method
        self._on_hand = 0
        self._units_sold = 0
        self._total_purchase_cost = ZERO_CENTS
        # -- fifo/lifo state -------------------------------------------------
        self._layers: list[tuple[int, Decimal]] = []  # (qty, unit_cost), oldest first
        self._cogs_cents = ZERO_CENTS                 # exact for fifo/lifo
        # -- weighted average state ------------------------------------------
        self._value = Fraction(0)                     # exact inventory value
        self._avg = Fraction(0)                       # exact moving average
        self._cogs_frac = Fraction(0)

    # ------------------------------------------------------------------ api

    @property
    def on_hand(self) -> int:
        return self._on_hand

    @property
    def average_unit_cost(self) -> Decimal | None:
        """Moving average unit cost at 4dp (weighted_average method only)."""
        if self.method != "weighted_average":
            return None
        if self._on_hand == 0:
            return ZERO_4DP
        return _to_4dp(self._avg)

    def apply(self, event: Event) -> None:
        if isinstance(event, Purchase):
            self._apply_purchase(event)
        elif isinstance(event, Sale):
            self._apply_sale(event)
        else:
            raise TypeError(f"unsupported event: {event!r}")

    def result(self) -> CostingResult:
        if self.method == "weighted_average":
            cogs = _to_cents(self._cogs_frac)
            avg = self.average_unit_cost
        else:
            cogs = self._cogs_cents.quantize(CENT)
            avg = None
        # Residual guarantees conservation to the cent under rounding.
        ending_value = self._total_purchase_cost - cogs
        return CostingResult(
            method=self.method,
            cogs=cogs,
            ending_quantity=self._on_hand,
            ending_value=ending_value,
            total_purchase_cost=self._total_purchase_cost,
            units_sold=self._units_sold,
            average_unit_cost=avg,
        )

    def run(self, events: Sequence[Event]) -> CostingResult:
        for event in events:
            self.apply(event)
        return self.result()

    # ------------------------------------------------------------ internals

    def _apply_purchase(self, event: Purchase) -> None:
        line_cost = event.unit_cost.quantize(CENT) * event.qty
        self._total_purchase_cost += line_cost
        self._on_hand += event.qty
        if self.method == "fifo":
            self._layers.append((event.qty, event.unit_cost))
        elif self.method == "lifo":
            self._layers.insert(0, (event.qty, event.unit_cost))
        else:  # weighted_average: recompute moving average from exact state
            self._value += event.qty * Fraction(event.unit_cost)
            self._avg = self._value / self._on_hand

    def _require(self, qty: int) -> None:
        if qty > self._on_hand:
            raise InsufficientInventoryError(
                f"cannot sell {qty}; only {self._on_hand} on hand"
            )

    def _apply_sale(self, event: Sale) -> None:
        self._require(event.qty)
        self._on_hand -= event.qty
        self._units_sold += event.qty
        remaining = event.qty

        if self.method == "fifo":
            while remaining:
                layer_qty, unit_cost = self._layers[0]
                take = min(layer_qty, remaining)
                self._cogs_cents += Decimal(take) * unit_cost
                remaining -= take
                if take == layer_qty:
                    self._layers.pop(0)
                else:
                    self._layers[0] = (layer_qty - take, unit_cost)
        elif self.method == "lifo":
            while remaining:
                layer_qty, unit_cost = self._layers[0]
                take = min(layer_qty, remaining)
                self._cogs_cents += Decimal(take) * unit_cost
                remaining -= take
                if take == layer_qty:
                    self._layers.pop(0)
                else:
                    self._layers[0] = (layer_qty - take, unit_cost)
        else:  # weighted_average: charge everything at the current average
            line = event.qty * self._avg          # exact Fraction arithmetic
            self._cogs_frac += line
            self._value -= line


def cost_inventory(events: Sequence[Event], method: str) -> CostingResult:
    """Convenience one-shot helper."""
    return InventoryLedger(method).run(events)

